import{_ as d,o as s,c as e,ag as a}from"./chunks/framework.C9sp7nFj.js";const O=JSON.parse('{"title":"MovJOffset 关节空间偏移","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovJOffset.md","filePath":"3. 指令/1. 运动指令/MovJOffset.md","lastUpdated":1778862643000}'),o={name:"3. 指令/1. 运动指令/MovJOffset.md"};function r(i,t,n,l,h,p){return s(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="movjoffset-关节空间偏移" tabindex="-1">MovJOffset 关节空间偏移 <a class="header-anchor" href="#movjoffset-关节空间偏移" aria-label="Permalink to &quot;MovJOffset 关节空间偏移&quot;">​</a></h1><p>关节空间偏移指令（MovJOffset）是指以<strong>指定的参考点</strong>为基准，相对于用户坐标系或工具坐标系进行位移偏移的关节运动指令。</p><p><strong>与 MovJRel 的区别：</strong></p><ul><li><strong>MovJRel</strong>：始终以&quot;当前位置&quot;或&quot;上一条指令终点&quot;为起点进行偏移。</li><li><strong>MovJOffset</strong>：由用户**显式指定一个参考位置（RP）**作为偏移起点，机器人不一定从当前位置出发，而是计算出 <code>参考点 + 偏移量</code> 的目标点并运动过去。</li></ul><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovJOffset(RP, TP, T, Tool, Coord, [V], [B], [C], [PayLoad], [DO])</p><p>MovJOffset(参考点, 偏移点, 目标点, 工具, 坐标系, [速度], [平滑], [姿态], [负载], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>RP</td><td>APOS 或 CPOS 变量</td><td>坐标系下的基准参考点位置。</td><td>必填</td></tr><tr><td>TP</td><td>DCPOS 或 DAPOS 变量</td><td>相对于参考位置（RP）需要移动的位置增量。</td><td>必填</td></tr><tr><td>T</td><td>enum（COORD / TOOL）</td><td>设置偏移增量参考的坐标系：<br><code>COORD</code>：参考用户坐标系。<br><code>TOOL</code>：参考工具坐标系。</td><td>必填</td></tr><tr><td>Tool</td><td>TOOL 变量</td><td>执行该运动时使用的工具参数。</td><td>必填</td></tr><tr><td>Coord</td><td>USERCOOR 变量</td><td>执行该运动时使用的用户坐标系参数。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定运动速度。在关节空间偏移中，仅 SPEED 变量中的 <code>per</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡值。</td><td>可选，默认 C100</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统设置的负载参数</td></tr><tr><td>[DO]</td><td>string</td><td>指令执行完后触发的 IO 操作（如 <code>SetDO</code>、<code>PulseOut</code> 等）。</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJOffset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, DAPOS0, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;COORD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">nullTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">World</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析：</strong></p><ol><li>机器人以 <strong>World</strong> 为坐标系，<strong>nullTool</strong> 为工具。</li><li>以点 <strong>P1</strong> 为参考基准。</li><li>计算出 P1 加上 <strong>DAPOS0</strong> 增量后的空间新位置。</li><li>机器人以关节运动方式、V50 的速度、C100 的过渡参数运动到该新位置。</li></ol>',17)])])}const f=d(o,[["render",r]]);export{O as __pageData,f as default};
